    private void updateChoice(){if(chooseButton==null)return;chooseButton.setEnabled(!selectedStock.isEmpty());if(!selectedStock.isEmpty())try{chooseButton.setText("使用 "+stocks.choose(this,selectedStock,getIntent().getStringExtra("format")).name);}catch(Exception e){selectedStock="";chooseButton.setText("选择一款胶片");chooseButton.setEnabled(false);}}
