    private void select(FilmStockStore.Stock stock){try{stocks.choose(this,stock.id,getIntent().getStringExtra("format"));if(stock.iso==0&&!getIntent().getBooleanExtra("originalOnly",false)){EditText input=new EditText(this);input.setInputType(InputType.TYPE_CLASS_NUMBER);input.setHint("1–102400");input.setContentDescription("本次装卷ISO");AlertDialog dialog=new AlertDialog.Builder(this).setTitle("来源未给出固定ISO").setMessage("请填写本次使用的ISO，不会改写片种或历史数据。").setView(input).setNegativeButton("取消",null).setPositiveButton("选择",null).create();dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{try{int iso=Integer.parseInt(input.getText().toString().trim());if(iso<1||iso>102400)throw new NumberFormatException();selected(stock,iso);dialog.dismiss();}catch(NumberFormatException invalid){input.setError("ISO须在1至102400之间");}}));dialog.show();return;}selected(stock,stock.iso);}catch(Exception error){Toast.makeText(this,error.getMessage(),1).show();}}
