    private void actions(FilmStockStore.Stock stock){if(stock.builtin){openDetail(stock);return;}new AlertDialog.Builder(this).setTitle(stock.title()).setItems(new String[]{"编辑",stock.archived?"恢复片种":"归档片种"},(d,w)->{if(w==0){formDraft=null;form(stock.id);}else{stocks.archive(stock.id,!stock.archived);rows();}}).show();}
    private void openDetail(FilmStockStore.Stock stock){startActivityForResult(new Intent(this,StockDetailActivity.class).putExtra("stock",stock.id).putExtra("format",getIntent().getStringExtra("format")).putExtra("select",getIntent().getBooleanExtra("select",false)),71);}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==71&&result==RESULT_OK&&data!=null){if(data.hasExtra("edit_stock")){formDraft=null;form(data.getStringExtra("edit_stock"));return;}if(data.getBooleanExtra("refresh_stocks",false)){render();return;}}if(request==71&&result==RESULT_OK&&data!=null)try{select(stocks.choose(this,data.getStringExtra("stock"),getIntent().getStringExtra("format")));}catch(Exception error){Toast.makeText(this,error.getMessage(),1).show();}}
    private EditText field(LinearLayout body,String label,String value,int type){int index=fields.size();body.addView(text(label,12,UiColors.color(getResources(),MUTED)));EditText input=new EditText(this);input.setTextColor(UiColors.color(getResources(),INK));input.setSingleLine(true);input.setTextSize(16);input.setInputType(type);input.setPadding(dp(12),dp(10),dp(12),dp(10));input.setBackground(surface(UiColors.color(getResources(),BG),16));input.setText(formDraft.getString("field"+index,value));input.setContentDescription(label);body.addView(input,new LinearLayout.LayoutParams(-1,dp(48)));fields.add(input);return input;}
    private void capture(){if(formDraft!=null)for(int i=0;i<fields.size();i++)formDraft.putString("field"+i,fields.get(i).getText().toString());}
    private void form(String id){FilmStockStore.Stock old=null;try{if(id!=null&&!id.isEmpty())old=stocks.get(id);}catch(IllegalArgumentException missing){formDraft=null;Toast.makeText(this,missing.getMessage(),1).show();return;}if(formDraft==null){formDraft=new Bundle();formDraft.putString("id",id==null?"":id);formDraft.putString("request",id==null||id.isEmpty()?UUID.randomUUID().toString():id);}fields.clear();LinearLayout body=column();body.setPadding(dp(16),dp(8),dp(16),dp(12));EditText brand=field(body,"品牌（可选）",old==null?"":old.brand,InputType.TYPE_CLASS_TEXT),name=field(body,"片种名称",old==null?"":old.name,InputType.TYPE_CLASS_TEXT),iso=field(body,"标称 ISO",old==null?"400":String.valueOf(old.iso),InputType.TYPE_CLASS_NUMBER),process=field(body,"冲洗工艺（可选，例如 C-41、黑白、E-6、ECN-2）",old==null?"":old.process,InputType.TYPE_CLASS_TEXT),power=field(body,"倒易律指数 p（可选，1–3）",old==null?"":old.power,InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL),formats=field(body,"适用规格（可选，逗号分隔；留空不限）",old==null?"":old.formats,InputType.TYPE_CLASS_TEXT);body.addView(text("倒易律按 t修正=t测得^p 计算，≤1秒不修正；留空时不提供自定义修正。已有胶卷保留原片种资料。",12,UiColors.color(getResources(),MUTED)));ScrollView scroll=new ScrollView(this);scroll.addView(body);String request=formDraft.getString("request");AlertDialog dialog=new AlertDialog.Builder(this).setTitle(old==null?"添加自定义片种":"编辑自定义片种").setView(scroll).setNegativeButton("取消",(d,w)->{formDraft=null;fields.clear();}).setPositiveButton("保存片种",null).create();dialog.setOnCancelListener(d->{formDraft=null;fields.clear();});dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{try{FilmStockStore.Stock stock=new FilmStockStore.Stock();stock.id=request;stock.brand=brand.getText().toString();stock.name=name.getText().toString();stock.iso=Integer.parseInt(iso.getText().toString().trim());stock.process=process.getText().toString();stock.power=power.getText().toString();stock.formats=formats.getText().toString();stocks.save(stock);formDraft=null;fields.clear();dialog.dismiss();archived=false;query="";render();}catch(Exception error){Toast.makeText(this,error instanceof NumberFormatException?"请填写有效的ISO整数":error.getMessage(),1).show();}}));dialog.show();if(dialog.getWindow()!=null){dialog.getWindow().setGravity(Gravity.BOTTOM);dialog.getWindow().setLayout(-1,-2);dialog.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE|WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_HIDDEN);}}
